func (q *Queries) UpdateOAuthResource(ctx context.Context, arg UpdateOAuthResourceParams) (OauthResource, error) {
	row := q.db.QueryRowContext(ctx, updateOAuthResource,
		arg.Name,
		arg.Scopes,
		arg.DynamicClients,
		arg.Uri,
	)
	var i OauthResource
	err := row.Scan(
		&i.ID,
		&i.Uri,
		&i.Name,
		&i.Scopes,
		&i.DynamicClients,
		&i.CreatedAt,
	)
	return i, err
}

